type Result<T, E> =
  | { ok: true; value: T }
  | { ok: false; error: E };

const ok = <T>(value: T): Result<T, never> => ({ ok: true, value });
const err = <E>(error: E): Result<never, E> => ({ ok: false, error });

function divide(a: number, b: number): Result<number, string> {
  return b === 0 ? err('division by zero') : ok(a / b);
}

function map<T, U, E>(r: Result<T, E>, fn: (t: T) => U): Result<U, E> {
  return r.ok ? ok(fn(r.value)) : r;
}

function andThen<T, U, E>(r: Result<T, E>, fn: (t: T) => Result<U, E>): Result<U, E> {
  return r.ok ? fn(r.value) : r;
}

const pipeline = andThen(divide(10, 2), (n) => ok(n.toFixed(2)));

type ApiError = { code: number; message: string };

async function getUser(id: string): Promise<Result<User, ApiError>> {
  try {
    const res = await fetch(`/api/users/${id}`);
    if (!res.ok) return err({ code: res.status, message: res.statusText });
    const raw: unknown = await res.json();
    if (!isUser(raw)) return err({ code: 502, message: 'Invalid shape' });
    return ok(raw);
  } catch {
    return err({ code: 0, message: 'Network failure' });
  }
}

function bad(): Result<number, string> {
  throw new Error('oops'); // caller expects .ok check
}

function handle(r: Result<number, string>) {
  if (r.ok) console.log(r.value);
  else console.error(r.error);
}

